31	// DispatchLifecycleEvent routes a normalized lifecycle event to the appropriate handler.
32	// Returns nil if the event was handled successfully.
33	func DispatchLifecycleEvent(ctx context.Context, ag agent.Agent, event *agent.Event) error {
34		if ag == nil {
35			return errors.New("agent cannot be nil")
36		}
37		if event == nil {
38			return errors.New("event cannot be nil")
39		}
40	
41		switch event.Type {
42		case agent.SessionStart:
43			return handleLifecycleSessionStart(ctx, ag, event)
44		case agent.TurnStart:
45			return handleLifecycleTurnStart(ctx, ag, event)
46		case agent.TurnEnd:
47			return handleLifecycleTurnEnd(ctx, ag, event)
48		case agent.Compaction:
49			return handleLifecycleCompaction(ctx, ag, event)
50		case agent.SessionEnd:
51			return handleLifecycleSessionEnd(ctx, ag, event)
52		case agent.SubagentStart:
53			return handleLifecycleSubagentStart(ctx, ag, event)
54		case agent.SubagentEnd:
55			return handleLifecycleSubagentEnd(ctx, ag, event)
56		case agent.ModelUpdate:
57			return handleLifecycleModelUpdate(ctx, ag, event)
58		default:
59			return fmt.Errorf("unknown lifecycle event type: %d", event.Type)
60		}
61	}
