157	// handleLifecycleModelUpdate persists the model name for the current session.
158	//
159	// If the session state file already exists (e.g., Gemini's BeforeModel fires
160	// after TurnStart), the model is written directly to state.ModelName — no hint
161	// file needed. Otherwise falls back to StoreModelHint for cross-process
162	// persistence (see its doc comment for the full rationale).
163	func handleLifecycleModelUpdate(ctx context.Context, ag agent.Agent, event *agent.Event) error {
164		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
165		logging.Info(logCtx, "model-update",
166			slog.String("session_id", event.SessionID),
167			slog.String("model", event.Model),
168		)
169	
170		if event.SessionID == "" || event.Model == "" {
171			return nil
172		}
173	
174		// Prefer writing directly to session state when it exists
175		state, loadErr := strategy.LoadSessionState(ctx, event.SessionID)
176		if loadErr != nil {
177			logging.Debug(logCtx, "could not load session state for model update, using hint file",
178				slog.String("error", loadErr.Error()))
179		}
180		if loadErr == nil && state != nil {
181			state.ModelName = event.Model
182			if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
183				logging.Warn(logCtx, "failed to update session state with model",
184					slog.String("error", saveErr.Error()))
185			}
186			return nil
187		}
188	
189		// State doesn't exist yet (or failed to load) — use hint file (see StoreModelHint doc)
190		if err := strategy.StoreModelHint(ctx, event.SessionID, event.Model); err != nil {
191			logging.Warn(logCtx, "failed to store model hint",
192				slog.String("error", err.Error()))
193		}
194	
195		return nil
196	}
