208	// UninstallHooks removes Entire hooks from Cursor HooksFileName.
209	// Unknown top-level fields and hook types are preserved on round-trip.
210	func (c *CursorAgent) UninstallHooks(ctx context.Context) error {
211		worktreeRoot, err := paths.WorktreeRoot(ctx)
212		if err != nil {
213			worktreeRoot = "."
214		}
215		hooksPath := filepath.Join(worktreeRoot, ".cursor", HooksFileName)
216		data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
217		if err != nil {
218			return nil //nolint:nilerr // No hooks file means nothing to uninstall
219		}
220	
221		var rawFile map[string]json.RawMessage
222		if err := json.Unmarshal(data, &rawFile); err != nil {
223			return fmt.Errorf("failed to parse "+HooksFileName+": %w", err)
224		}
225	
226		var rawHooks map[string]json.RawMessage
227		if hooksRaw, ok := rawFile["hooks"]; ok {
228			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
229				return fmt.Errorf("failed to parse hooks in "+HooksFileName+": %w", err)
230			}
231		}
232		if rawHooks == nil {
233			rawHooks = make(map[string]json.RawMessage)
234		}
235	
236		// Parse only the hook types we manage
237		var sessionStart, sessionEnd, beforeSubmitPrompt, stop, preCompact, subagentStart, subagentStop []CursorHookEntry
238		parseCursorHookType(rawHooks, "sessionStart", &sessionStart)
239		parseCursorHookType(rawHooks, "sessionEnd", &sessionEnd)
240		parseCursorHookType(rawHooks, "beforeSubmitPrompt", &beforeSubmitPrompt)
241		parseCursorHookType(rawHooks, "stop", &stop)
242		parseCursorHookType(rawHooks, "preCompact", &preCompact)
243		parseCursorHookType(rawHooks, "subagentStart", &subagentStart)
244		parseCursorHookType(rawHooks, "subagentStop", &subagentStop)
245	
246		// Remove Entire hooks from all hook types
247		sessionStart = removeEntireHooks(sessionStart)
248		sessionEnd = removeEntireHooks(sessionEnd)
249		beforeSubmitPrompt = removeEntireHooks(beforeSubmitPrompt)
250		stop = removeEntireHooks(stop)
251		preCompact = removeEntireHooks(preCompact)
252		subagentStart = removeEntireHooks(subagentStart)
253		subagentStop = removeEntireHooks(subagentStop)
254	
255		// Marshal modified hook types back into rawHooks
256		marshalCursorHookType(rawHooks, "sessionStart", sessionStart)
257		marshalCursorHookType(rawHooks, "sessionEnd", sessionEnd)
258		marshalCursorHookType(rawHooks, "beforeSubmitPrompt", beforeSubmitPrompt)
259		marshalCursorHookType(rawHooks, "stop", stop)
260		marshalCursorHookType(rawHooks, "preCompact", preCompact)
261		marshalCursorHookType(rawHooks, "subagentStart", subagentStart)
262		marshalCursorHookType(rawHooks, "subagentStop", subagentStop)
263	
264		// Marshal hooks back (preserving unknown hook types)
265		if len(rawHooks) > 0 {
266			hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
267			if err != nil {
268				return fmt.Errorf("failed to marshal hooks: %w", err)
269			}
270			rawFile["hooks"] = hooksJSON
271		} else {
272			delete(rawFile, "hooks")
273		}
274	
275		// Write back
276		output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
277		if err != nil {
278			return fmt.Errorf("failed to marshal "+HooksFileName+": %w", err)
279		}
280	
281		if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
282			return fmt.Errorf("failed to write "+HooksFileName+": %w", err)
283		}
284	
285		return nil
286	}
