326	// parseCursorHookType parses a specific hook type from rawHooks into the target slice.
327	// Silently ignores parse errors (leaves target unchanged).
328	func parseCursorHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]CursorHookEntry) {
329		if data, ok := rawHooks[hookType]; ok {
330			//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
331			json.Unmarshal(data, target)
332		}
333	}
334	
335	// marshalCursorHookType marshals a hook type back into rawHooks.
336	// If the slice is empty, removes the key from rawHooks.
337	func marshalCursorHookType(rawHooks map[string]json.RawMessage, hookType string, entries []CursorHookEntry) {
338		if len(entries) == 0 {
339			delete(rawHooks, hookType)
340			return
341		}
342		data, err := jsonutil.MarshalWithNoHTMLEscape(entries)
343		if err != nil {
344			return // Silently ignore marshal errors (shouldn't happen)
345		}
346		rawHooks[hookType] = data
347	}
