360	func isEntireHook(command string) bool {
361		return agent.IsManagedHookCommand(command, entireHookPrefixes)
362	}
363	
364	func hasEntireHook(entries []CursorHookEntry) bool {
365		for _, entry := range entries {
366			if isEntireHook(entry.Command) {
367				return true
368			}
369		}
370		return false
371	}
372	
373	func removeEntireHooks(entries []CursorHookEntry) []CursorHookEntry {
374		result := make([]CursorHookEntry, 0, len(entries))
375		for _, entry := range entries {
376			if !isEntireHook(entry.Command) {
377				result = append(result, entry)
378			}
379		}
380		return result
381	}
