// AcquireSessionLock takes an exclusive per-session-id lock under the session
// state directory. Used to serialize concurrent processes that initialize the
// same session — when Cursor IDE forwards a single user prompt to both its
// own hook system and Claude Code's, two `entire` hook processes can otherwise
// each create-from-scratch in parallel and race for the last write. With the
// lock the second arrival sees the existing state and goes through the cheap
// update path (correctSessionAgentType repairs AgentType if the transcript
// path indicates a different agent).
func AcquireSessionLock(ctx context.Context, sessionID string) (*filelock.Lock, error) {
	if err := validation.ValidateSessionID(sessionID); err != nil {
		return nil, fmt.Errorf("invalid session ID: %w", err)
	}
	stateDir, err := getSessionStateDir(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get session state directory: %w", err)
	}
	if err := os.MkdirAll(stateDir, 0o750); err != nil {
		return nil, fmt.Errorf("failed to create session state directory: %w", err)
	}
	return filelock.Acquire(filepath.Join(stateDir, sessionID+".lock"))
}

